#include <cassert>
#include <cmath>
#include <cstdio>
#include "competition_shadow.h"
using namespace competition_shadow;
static SensorInput healthy(uint64_t t,AuthoritativeSafety safety=AuthoritativeSafety::Running){SensorInput x{};x.nowUs=t;x.safety=safety;x.heartbeat=x.imuValid=x.tofValid=x.gnssValid=true;x.heartbeatUs=x.imuUs=x.tofUs=x.gnssUs=t;x.tofM=1.2f;return x;}
int main(){Config cfg{};cfg.slewPerStep=1;cfg.autoPropulsion=.3f;Controller c(cfg);SensorInput x=healthy(1000000);assert(c.setMode(ControlMode::Manual,1,AuthoritativeSafety::Disarmed).ack==Ack::Accepted);assert(c.setMode(ControlMode::HeadingHold,2,AuthoritativeSafety::Running).ack==Ack::Rejected);ManualCommand m{.2f,-.3f,.4f,.5f,3,1,0};assert(c.setManual(m,x.nowUs).ack==Ack::Accepted);Output o=c.step(x);assert(o.safety==AuthoritativeSafety::Running&&o.leftFront==.2f&&o.rightFront==-.3f&&o.rearYaw==.4f&&o.propulsion==.5f&&!o.physicalGate);x.nowUs+=500001;x.heartbeatUs=x.nowUs;o=c.step(x);assert(o.safetyRequest==SafetyRequest::Disarm&&o.reason==StopReason::ManualTimeout);assert(c.setMode(ControlMode::AttitudeAssist,4,AuthoritativeSafety::Disarmed).ack==Ack::Accepted);x=healthy(2000000);assert(c.setManual(m,x.nowUs).ack==Ack::Accepted);o=c.step(x);assert(o.leftPrelimit==o.rightPrelimit);c.reset();assert(c.setMode(ControlMode::HeadingHold,5,AuthoritativeSafety::Disarmed).ack==Ack::Accepted);x=healthy(3000000);x.yawRad=3.13f;assert(c.setManual(m,x.nowUs).ack==Ack::Accepted);o=c.step(x);assert(std::fabs(o.targetYaw-3.13f)<.001f);assert(c.setHeading(-3.13f,6).ack==Ack::Accepted);o=c.step(x);assert(std::fabs(o.uYaw)<.1f);c.reset();Waypoint route[2]={{0,0},{3,0}};assert(c.setWaypoints(route,2,7,AuthoritativeSafety::Disarmed).ack==Ack::Accepted);assert(c.setMode(ControlMode::AutoWaypoint,8,AuthoritativeSafety::Disarmed).ack==Ack::Accepted);x=healthy(4000000);o=c.step(x);assert(o.waypointReached);x.nowUs+=20000;x.heartbeatUs=x.imuUs=x.tofUs=x.gnssUs=x.nowUs;x.northM=3;o=c.step(x);assert(o.safetyRequest==SafetyRequest::Disarm&&o.reason==StopReason::FinalWaypoint);x=healthy(5000000,AuthoritativeSafety::EStop);o=c.step(x);assert(o.leftFront==0&&o.propulsion==0&&o.reason==StopReason::EStop);PhysicalConfig p{};assert(!Controller::physicalConfigurationValid(p));p={0,1,2,3,1000,1500,2000,1000,1500,2000,1000,1500,2000,1000,1500,2000,true};assert(Controller::physicalConfigurationValid(p));assert(c.physicalWriteCount()==0);std::puts("COMPETITION_SHADOW_HOST_PASS authoritative_safety=ok modes=4 gate_closed=ok");}